첫 줄의 숫자는 공백 하나로 나눠 적어요.

```c
#include <stdio.h>

int down(int n) {
    if (n <= 0) {
        return 0;
    }
    printf("%d ", n);
    int r = down(n - 2) * 2 + n;
    printf("%d ", r);
    return r;
}

int main(void) {
    int total = down(5);
    printf("\n%d\n", total);
    return 0;
}
```

